    private static bool IsModel(JsonElement json, int index)
    {
        var candidates = Enumerable.Range(0, Models.Length).Where(i => Models[i].Matches(json)).ToList();
        if (candidates.Any(i => Models[i].Variant)) candidates.RemoveAll(i => !Models[i].Variant);
        int Unknown(int i) => json.EnumerateObject().Count(p => !Models[i].Keys.Contains(p.Name));
        var best = candidates.OrderBy(Unknown).ThenBy(i => Models[i].Keys.Count).ThenBy(i => i).FirstOrDefault(-1);
        return best >= 0 && candidates.Contains(index) && Models[index].Keys.SetEquals(Models[best].Keys);
    }

